	private escalationTimeouts: Map<string, NodeJS.Timeout[]>;

	constructor(
		logger: ILogger,
		networkService: INetworkService,
		statusService: IStatusService,
		notificationsService: INotificationsService,
		checkService: ICheckService,
		settingsService: ISettingsService,
		buffer: IBufferService,
		incidentService: IncidentService,
		maintenanceWindowsRepository: IMaintenanceWindowsRepository,
		monitorsRepository: IMonitorsRepository,
		teamsRepository: ITeamsRepository,
		monitorStatsRepository: IMonitorStatsRepository,
		checksRepository: IChecksRepository,
		incidentsRepository: IIncidentsRepository,
		geoChecksService: IGeoChecksService,
		geoChecksRepository: IGeoChecksRepository
	) {
		this.logger = logger;
		this.networkService = networkService;
		this.statusService = statusService;
		this.checkService = checkService;
		this.settingsService = settingsService;
		this.buffer = buffer;
		this.notificationsService = notificationsService;
		this.incidentService = incidentService;
		this.maintenanceWindowsRepository = maintenanceWindowsRepository;
		this.monitorsRepository = monitorsRepository;
		this.teamsRepository = teamsRepository;
		this.monitorStatsRepository = monitorStatsRepository;
		this.checksRepository = checksRepository;
		this.incidentsRepository = incidentsRepository;
		this.geoChecksService = geoChecksService;
		this.geoChecksRepository = geoChecksRepository;
		this.escalationTimeouts = new Map()

	private scheduleEscalationNotifications(monitor: Monitor, status: string, decision: MonitorActionDecision): void {
		if (!monitor.escalationNotifications || monitor.escalationNotifications.length === 0) {
			return;
		}

		const enabledEscalations = monitor.escalationNotifications.filter(esc => esc.enabled);
		if (enabledEscalations.length === 0) {
			return;
		}

		// Clear any existing timeouts for this monitor
		this.clearEscalationTimeouts(monitor.id);

		const timeouts: NodeJS.Timeout[] = [];

		for (const escalation of enabledEscalations) {
			const delayMs = escalation.delay * 60 * 1000; // Convert minutes to milliseconds

			const timeout = setTimeout(async () => {
				try {
					// Re-fetch the monitor to check current status
					const currentMonitor = await this.monitorsRepository.findById(monitor.id);
					if (!currentMonitor) {
						this.logger.warn({
							message: `Monitor ${monitor.id} not found during escalation check`,
							service: SERVICE_NAME,
							method: "scheduleEscalationNotifications",
						});
						return;
					}

					// Only send escalation if monitor is still down
					if (currentMonitor.status === "down") {
						// Send escalation notifications directly
						await this.sendEscalationNotifications(currentMonitor, escalation.contacts);
					}
				} catch (error: unknown) {
					this.logger.error({
						message: `Error processing escalation for monitor ${monitor.id}: ${error instanceof Error ? error.message : "Unknown error"}`,
						service: SERVICE_NAME,
						method: "scheduleEscalationNotifications",
						stack: error instanceof Error ? error.stack : undefined,
					});
				}
			}, delayMs);

			timeouts.push(timeout);
		}

		this.escalationTimeouts.set(monitor.id, timeouts);
	}

	private clearEscalationTimeouts(monitorId: string): void {
		const timeouts = this.escalationTimeouts.get(monitorId);
		if (timeouts) {
			for (const timeout of timeouts) {
				clearTimeout(timeout);
			}
			this.escalationTimeouts.delete(monitorId);
		}
	}

	private async sendEscalationNotifications(monitor: Monitor, contacts: { type: string; address: string }[]): Promise<void> {
		// Use the existing notifications service to send escalation alerts
		// We'll create a mock decision object for escalation
		const escalationDecision: MonitorActionDecision = {
			shouldCreateIncident: false,
			shouldResolveIncident: false,
			shouldSendNotification: true,
			incidentReason: null,
			notificationReason: "status_change", // Treat as status change for escalation
		};

		// Send notifications using the existing service
		await this.notificationsService.handleNotifications(monitor, "down", escalationDecision);
	}

