					console.log(`[ESCALATION] Re-fetching monitor ${monitor.id} to check current status`);
					const currentMonitor = await this.monitorsRepository.findById(monitor.id, monitor.teamId);
					if (!currentMonitor) {
						console.log(`[ESCALATION] Monitor ${monitor.id} not found during escalation check`);
						this.logger.warn({
							message: `Monitor ${monitor.id} not found during escalation check`,
							service: SERVICE_NAME,
							method: "scheduleEscalationNotifications",
						});
						return;
					}

