						service: SERVICE_NAME,
						method: "scheduleEscalationNotifications",
						stack: error instanceof Error ? error.stack : undefined,
					});
				}
			}, delayMs);

			timeouts.push(timeout);
		}

		this.escalationTimeouts.set(monitor.id, timeouts);
